{
  "contract": "GoodMorning",
  "closure": {
    "site_function": "swapBack",
    "site_call": ".addLiquidityETH",
    "functions": [
      "transfer",
      "transferFrom",
      "approve"
    ],
    "justification": "All public/external functions that can affect _rOwned or _totalProportion must be included to ensure soundness."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom",
      "approve"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1,
      "approve": 1
    }
  },
  "phases": {
    "function": "swapBack",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .addLiquidityETH"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .addLiquidityETH",
      "to_marker": "after .addLiquidityETH"
    },
    "post": {
      "name": "post",
      "from_marker": "after .addLiquidityETH",
      "to_marker": "exit"
    },
    "linearization_point": "after .addLiquidityETH"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of _rOwned in-flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__rOwned == _totalProportion + inFlight",
    "stable_formula": "_sum__rOwned == _totalProportion",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__rOwned == _totalProportion",
    "rule": "The exposure invariant ensures that the sum of _rOwned remains consistent with _totalProportion, accounting for in-flight changes during callbacks."
  }
}
